/**
 * @module BatchList
 *
 * Gestão de lotes (batches) de produtos no estoque.
 * Permite criar novos lotes, ajustar quantidades com debounce,
 * excluir lotes e exibe status de validade com cores.
 */

import React, { useState, useEffect } from 'react';
import {
  Plus,
  AlertTriangle,
  Calendar,
  Package,
  Minus,
} from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import { Badge } from '@/shared/ui/badge';
import { Popover, PopoverContent, PopoverTrigger } from '@/shared/ui/popover';
import { Calendar as CalendarComponent } from '@/shared/ui/calendar';
import { format, addDays, parseISO } from 'date-fns';
import { cn } from '@/shared/lib/utils';
import { supabase } from '@/integrations/supabase/client';
import { useToast } from '@/shared/hooks/use-toast';

interface BatchData {
  id: string; // lote_id
  codigo: string;
  validade: string;
  fabricacao: string | null;
}

interface StockBatch {
  id: string; // estoque_lotes id
  lote_id: string;
  quantidade: number;
  lotes: BatchData;
}

interface BatchListProps {
  produtoId: number;
  storeId: number;
  produtoNome: string;
  diasValidadePadrao?: number;
  onUpdate?: () => void;
}

/**
 * Lista e gerencia lotes de um produto em uma loja específica.
 * Permite criar lotes com datas de fabricação/validade, ajustar quantidades
 * (com debounce de 1s e registro de movimentação) e excluir lotes.
 *
 * @param produtoId - ID do produto master.
 * @param storeId - ID da loja no estoque.
 * @param produtoNome - Nome do produto (para exibição).
 * @param diasValidadePadrao - Dias de validade padrão para auto-preencher data.
 * @param onUpdate - Callback chamado após qualquer alteração nos lotes.
 */
export function BatchList({
  produtoId,
  storeId,
  produtoNome,
  diasValidadePadrao,
  onUpdate,
}: BatchListProps) {
  const [batches, setBatches] = useState<StockBatch[]>([]);
  const [loading, setLoading] = useState(false);
  const pendingUpdates = React.useRef<Record<string, number>>({});
  const updateTimeouts = React.useRef<Record<string, number>>({});

  // New Batch Form
  const [newFabricacao, setNewFabricacao] = useState<Date | undefined>(
    new Date(),
  );
  const [newValidade, setNewValidade] = useState<Date | undefined>(
    diasValidadePadrao ? addDays(new Date(), diasValidadePadrao) : undefined,
  );
  const [newQtd, setNewQtd] = useState('');
  const [isAdding, setIsAdding] = useState(false);

  const { toast } = useToast();

  useEffect(() => {
    fetchBatches();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [produtoId, storeId]);

  useEffect(() => {
    if (newFabricacao && diasValidadePadrao) {
      setNewValidade(addDays(newFabricacao, diasValidadePadrao));
    }
  }, [newFabricacao, diasValidadePadrao]);

  const fetchBatches = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('estoque_lotes' as any)
        .select(
          `
                    id,
                    lote_id,
                    quantidade,
                    lotes (
                        id,
                        codigo,
                        data_validade,
                        data_fabricacao
                    )
                `,
        )
        .eq('produto_id', produtoId)
        .eq('loja_id', storeId);

      if (error) throw error;

      // Caixa vazia (qtd 0) "some" da tela — saldo zerado não é caixa.
      const visiveis = ((data || []) as any[]).filter(
        (r) => Number(r.quantidade) > 0,
      );
      const sorted = visiveis.sort((a, b) => {
        const dateA = new Date(a.lotes.data_validade).getTime();
        const dateB = new Date(b.lotes.data_validade).getTime();
        return dateA - dateB;
      });

      setBatches(sorted);
    } catch (error) {
      console.error('Error fetching batches:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleAddBatch = async () => {
    if (!newFabricacao || !newValidade || !newQtd) {
      toast({ title: 'Preencha todos os campos', variant: 'destructive' });
      return;
    }

    }, 1000);
  };

  // Sem exclusão de lote/caixa: a caixa só se MOVE (entrada/saída). Para "tirar"
  // o saldo, ajuste para 0 — a caixa vazia some da lista (filtro em fetchBatches).

  const getExpiryStatus = (dateStr: string) => {
    const today = new Date();
    const expiry = parseISO(dateStr);
    const daysUntil = (expiry.getTime() - today.getTime()) / (1000 * 3600 * 24);

    if (daysUntil < 0)
      return {
        color: 'text-red-600 bg-red-50 border-red-200',
        label: 'Vencido',
        icon: AlertTriangle,
      };
    if (daysUntil < 30)
      return {
        color: 'text-orange-600 bg-orange-50 border-orange-200',
        label: 'Vence em breve',
        icon: AlertTriangle,
      };
    return {
      color: 'text-green-600 bg-green-50 border-green-200',
      label: 'Ok',
      icon: Calendar,
    };
  };

  return (
    <div className="w-full bg-white/40 dark:bg-black/20 rounded-xl border border-[#57715B]/10 p-4 space-y-4">
      <div className="flex items-center justify-between">
        <h4 className="text-sm font-bold text-[#57715B] dark:text-[#E6DCCF] uppercase tracking-wider flex items-center gap-2">
          <Package className="w-4 h-4" /> Gestão de Lotes
        </h4>
        <Button
          variant="outline"
          size="sm"
          onClick={() => setIsAdding(!isAdding)}
          className="h-7 text-xs gap-1 border-[#57715B]/30 text-[#57715B] hover:bg-[#57715B]/10"
        >
          <Plus className="w-3 h-3" /> {isAdding ? 'Cancelar' : 'Novo Lote'}
        </Button>
      </div>

      {isAdding && (
        <div className="bg-white/60 dark:bg-black/40 p-3 rounded-lg border border-[#57715B]/10 space-y-3 animate-in slide-in-from-top-2">
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
            <Popover>
              <PopoverTrigger asChild>
                <Button
                  variant="outline"
                  className={cn(
                    'h-8 text-xs justify-start text-left font-normal',
                    !newFabricacao && 'text-muted-foreground',
                  )}
                >
                  <Calendar className="mr-2 h-3 w-3" />
                  {newFabricacao
                    ? format(newFabricacao, 'dd/MM/yyyy')
                    : 'Fabricação'}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0">
                <CalendarComponent
                  mode="single"
                  selected={newFabricacao}
                  onSelect={setNewFabricacao}
                  initialFocus
                />
              </PopoverContent>
            </Popover>
            <Popover>
              <PopoverTrigger asChild>
                <Button
                  variant="outline"
                  className={cn(
                    'h-8 text-xs justify-start text-left font-normal',
                    !newValidade && 'text-muted-foreground',
                  )}
                >
                  <Calendar className="mr-2 h-3 w-3" />
                  {newValidade ? format(newValidade, 'dd/MM/yyyy') : 'Validade'}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0">
                <CalendarComponent
                  mode="single"
                  selected={newValidade}
                  onSelect={setNewValidade}
                  initialFocus
                />
              </PopoverContent>
            </Popover>
            <Input data-mia-field="new_qtd"
              type="number"
              placeholder="Qtd Inicial"
              value={newQtd}
              onChange={(e) => setNewQtd(e.target.value)}
              className="h-8 text-xs"
            />
          </div>
          <Button data-mia-action="add-batch"
            size="sm"
            onClick={handleAddBatch}
            className="w-full h-7 bg-[#57715B] text-white hover:bg-[#57715B]/90 text-xs"
          >
            Criar Lote e Adicionar ao Estoque
          </Button>
        </div>
      )}

      <div className="space-y-2">
        {batches.length === 0 ? (
          <div className="text-center py-4 text-xs text-muted-foreground bg-black/5 rounded-lg border border-dashed border-black/10">
            Nenhum lote neste estoque.
          </div>
        ) : (
          batches.map((batch) => {
            const status = getExpiryStatus(batch.lotes.data_validade);
            const StatusIcon = status.icon;
            return (
              <div
                key={batch.id}
                className="flex flex-col sm:flex-row items-start sm:items-center justify-between p-3 bg-white/60 dark:bg-black/40 rounded-lg border border-[#57715B]/10 gap-3"
              >
                <div className="flex-1 space-y-1">
                  <div className="flex items-center gap-2">
                    <span className="font-mono font-bold text-sm text-foreground">
                      {batch.lotes.codigo}
                    </span>
                    <Badge
                      variant="outline"
                      className={cn(
                        'text-[10px] h-5 px-1.5 gap-1',
                        status.color,
                      )}
                    >
                      <StatusIcon className="w-3 h-3" />
                      Val:{' '}
                      {format(
                        parseISO(batch.lotes.data_validade),
                        'dd/MM/yyyy',
                      )}
                    </Badge>
                    {batch.lotes.data_fabricacao && (
                      <Badge
                        variant="outline"
                        className="text-[10px] h-5 px-1.5 gap-1 text-gray-500 border-gray-200"
                      >
                        Fab:{' '}
                        {format(
                          parseISO(batch.lotes.data_fabricacao),
                          'dd/MM/yyyy',
                        )}
                      </Badge>
                    )}
                  </div>
                  <div className="text-[10px] text-muted-foreground uppercase tracking-wider font-bold">
                    {status.label}
                  </div>
                </div>

                <div className="flex items-center gap-3">
                  <div className="flex items-center gap-1 bg-white dark:bg-black rounded-lg border border-gray-200 dark:border-gray-800 p-0.5">
                    <Button
                      variant="ghost"
                      size="icon"
                      className="h-7 w-7 rounded-md hover:bg-gray-100 dark:hover:bg-gray-800"
                      onClick={() =>
                        adjustQuantity(
                          batch.id,
                          batch.quantidade,
                          -1,
                          batch.lote_id,
                        )
                      }
                    >
                      <Minus className="w-3 h-3" />
                    </Button>
                    <span className="w-12 text-center font-mono font-bold text-sm">
                      {batch.quantidade}
                    </span>
                    <Button
                      variant="ghost"
                      size="icon"
                      className="h-7 w-7 rounded-md hover:bg-gray-100 dark:hover:bg-gray-800"
                      onClick={() =>
                        adjustQuantity(
                          batch.id,
                          batch.quantidade,
                          +1,
                          batch.lote_id,
                        )
                      }
                    >
                      <Plus className="w-3 h-3" />
                    </Button>
                  </div>
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
}

