import React, { useState, useEffect } from "react";
import { Plus, AlertTriangle, Calendar, Package } from "lucide-react";
import { Button } from "@/shared/ui/button";
import { Input } from "@/shared/ui/input";
import { Badge } from "@/shared/ui/badge";
import { Popover, PopoverContent, PopoverTrigger } from "@/shared/ui/popover";
import { Calendar as CalendarComponent } from "@/shared/ui/calendar";
import { format, addDays, parseISO } from "date-fns";
import { cn } from "@/shared/lib/utils";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/shared/hooks/use-toast";
import { handleError } from '@/shared/lib/error-handler';

interface StockBatch {
    id: string; // lote_id
    codigo: string;
    data_validade: string;
    data_fabricacao: string | null;
}

interface BatchListProps {
    produtoId: number;
    storeId: number;
    produtoNome: string;
    diasValidadePadrao?: number;
    onUpdate?: () => void;
}

export function BatchList({ produtoId, storeId, produtoNome, diasValidadePadrao, onUpdate }: BatchListProps) {
    const [batches, setBatches] = useState<StockBatch[]>([]);
    const [loading, setLoading] = useState(false);

    // New Batch Form
    const [newFabricacao, setNewFabricacao] = useState<Date | undefined>(new Date());
    const [newValidade, setNewValidade] = useState<Date | undefined>(
        diasValidadePadrao ? addDays(new Date(), diasValidadePadrao) : undefined
    );
    const [isAdding, setIsAdding] = useState(false);

    const { toast } = useToast();

    useEffect(() => {
        fetchBatches();
    }, [produtoId, storeId]);

    useEffect(() => {
        if (newFabricacao && diasValidadePadrao) {
            setNewValidade(addDays(newFabricacao, diasValidadePadrao));
        }
    }, [newFabricacao, diasValidadePadrao]);

    const fetchBatches = async () => {
        setLoading(true);
        try {
            const { data, error } = await supabase
                .from('lotes')
                .select(`
                    id,
                    codigo,
                    data_validade,
                    data_fabricacao
                `)
                .eq('produto_id', produtoId)
                .eq('loja_id', storeId);

            if (error) throw error;

            const sorted = ((data || []) as any[]).sort((a, b) => {
                // Sort by creation or validity? Let's sort by validity descending (newest expiry first)
                const dateA = new Date(a.data_validade).getTime();
                const dateB = new Date(b.data_validade).getTime();
                return dateB - dateA; // Descending
            });

            setBatches(sorted);

        } catch (error) {
            handleError(error, { domain: 'logistica', operation: 'fetchBatches', showToast: false });
        } finally {
            setLoading(false);
        }
    };

    const handleAddBatch = async () => {
        if (!newFabricacao || !newValidade) {
            toast({ title: "Preencha todos os campos", variant: "destructive" });
            return;
        }

        const fabricacaoStr = format(newFabricacao, 'ddMMyyyy');
        // Removed time from batch code to make it cleaner (requested by user)
        // Old format: L{ddMMyyyy}{HHmm} -> L270220261430
        // New format: L{ddMMyyyy} -> L27022026
        const generatedLoteCode = `L${fabricacaoStr}`;

        try {
            // Criação idempotente: reaproveita o lote existente (mesmo produto+código)
            // em vez de criar um id divergente. Evita orfanizar etiquetas já impressas.
            const { error: loteError } = await (supabase.rpc as any)('find_or_create_lote', {
                p_produto_id: produtoId,
                p_codigo: generatedLoteCode,
                p_data_validade: format(newValidade, 'yyyy-MM-dd'),
                p_data_fabricacao: format(newFabricacao, 'yyyy-MM-dd'),
                p_loja_id: storeId,
            });

            if (loteError) throw loteError;

            // NÃO criar estoque_lotes com quantidade=0 na criação do lote.
            // O trigger sync_estoque_from_lotes calcula SUM(quantidade) e zeraria
            // o estoque existente. A row em estoque_lotes deve ser criada
            // apenas quando houver entrada real de quantidade (via bipe/recebimento).
            // Hardened 2026-05-20.

            toast({ title: `Lote ${generatedLoteCode} criado com sucesso!` });

            setNewFabricacao(new Date());
            setIsAdding(false);

            fetchBatches();
            onUpdate?.();

        } catch (e: any) {
            handleError(e, { domain: 'logistica', operation: 'addBatch', showToast: false });
            toast({
                title: "Erro ao criar lote",
                description: e.message || "Verifique os dados e tente novamente",
                variant: "destructive"
            });
        }
    };

    // Lote é identidade permanente (produto + código + validade) e é referenciado
    // por movimentações e etiquetas_qr. Apagar lote orfaniza etiquetas (FK SET NULL)
    // e quebra inserts de movimentação (23503). Por isso NÃO existe mais excluir
    // lote: a caixa apenas se MOVE (entrada/saída). Cf. modelo de logística.

    // Helper to format date avoiding timezone issues (treats YYYY-MM-DD as local date)
    const formatDate = (dateStr: string) => {
        if (!dateStr) return '--/--/----';
        // Append time to force local time interpretation or avoid UTC shift if browser is behind UTC
        // The safest way for display is to parse the parts manually or append T12:00:00
        const date = new Date(dateStr + 'T12:00:00'); 
        return format(date, "dd/MM/yyyy");
    };

    const getExpiryStatus = (dateStr: string) => {
        const today = new Date();
        const expiry = new Date(dateStr + 'T12:00:00'); // Consistent parsing
        const daysUntil = (expiry.getTime() - today.getTime()) / (1000 * 3600 * 24);

        if (daysUntil < 0) return { color: "text-red-600 bg-red-50 border-red-200", label: "Vencido", icon: AlertTriangle };
        if (daysUntil < 30) return { color: "text-orange-600 bg-orange-50 border-orange-200", label: "Vence em breve", icon: AlertTriangle };
        return { color: "text-green-600 bg-green-50 border-green-200", label: "Ok", icon: Calendar };
    };

    return (
        <div className="w-full bg-white/40 dark:bg-black/20 rounded-xl border border-[#57715B]/10 p-4 space-y-4">
            <div className="flex items-center justify-between">
                <h4 className="text-sm font-bold text-[#57715B] dark:text-[#E6DCCF] uppercase tracking-wider flex items-center gap-2">
                    <Package className="w-4 h-4" /> Gestão de Lotes
                </h4>
                <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setIsAdding(!isAdding)}
                    className="h-7 text-xs gap-1 border-[#57715B]/30 text-[#57715B] hover:bg-[#57715B]/10"
                >
                    <Plus className="w-3 h-3" /> {isAdding ? "Cancelar" : "Novo Lote"}
                </Button>
            </div>

            {isAdding && (
                <div className="bg-white/60 dark:bg-black/40 p-3 rounded-lg border border-[#57715B]/10 space-y-3 animate-in slide-in-from-top-2">
                    <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
                        <Popover>
                            <PopoverTrigger asChild>
                                <Button variant="outline" className={cn("h-8 text-xs justify-start text-left font-normal", !newFabricacao && "text-muted-foreground")}>
                                    <Calendar className="mr-2 h-3 w-3" />
                                    {newFabricacao ? format(newFabricacao, "dd/MM/yyyy") : "Fabricação"}
                                </Button>
                            </PopoverTrigger>
                            <PopoverContent className="w-auto p-0">
                                <CalendarComponent mode="single" selected={newFabricacao} onSelect={setNewFabricacao} initialFocus />
                            </PopoverContent>
                        </Popover>
                        <Popover>
                            <PopoverTrigger asChild>
                                <Button variant="outline" className={cn("h-8 text-xs justify-start text-left font-normal", !newValidade && "text-muted-foreground")}>
                                    <Calendar className="mr-2 h-3 w-3" />
                                    {newValidade ? format(newValidade, "dd/MM/yyyy") : "Validade"}
                                </Button>
                            </PopoverTrigger>
                            <PopoverContent className="w-auto p-0">
                                <CalendarComponent mode="single" selected={newValidade} onSelect={setNewValidade} initialFocus />
                            </PopoverContent>
                        </Popover>
                    </div>
                    <Button data-mia-action="add-batch" size="sm" onClick={handleAddBatch} className="w-full h-7 bg-[#57715B] text-white hover:bg-[#57715B]/90 text-xs">
                        Criar Lote (Sem Saldo)
                    </Button>
                </div>
            )}

            <div className="space-y-2 max-h-[60vh] overflow-y-auto pr-1">
                {batches.length === 0 ? (
                    <div className="text-center py-4 text-xs text-muted-foreground bg-black/5 rounded-lg border border-dashed border-black/10">
                        Nenhum lote neste estoque.
                    </div>
                ) : (
                    batches.map(batch => {
                        const status = getExpiryStatus(batch.data_validade);
                        const StatusIcon = status.icon;
                        return (
                            <div key={batch.id} className="flex flex-col sm:flex-row items-start sm:items-center justify-between p-3 bg-white/60 dark:bg-black/40 rounded-lg border border-[#57715B]/10 gap-3">
                                <div className="flex-1 space-y-1">
                                    <div className="flex items-center gap-2">
                                        <span className="font-mono font-bold text-sm text-foreground">{batch.codigo}</span>
                                        <Badge variant="outline" className={cn("text-[10px] h-5 px-1.5 gap-1", status.color)}>
                                            <StatusIcon className="w-3 h-3" />
                                            Val: {formatDate(batch.data_validade)}
                                        </Badge>
                                        {batch.data_fabricacao && (
                                            <Badge variant="outline" className="text-[10px] h-5 px-1.5 gap-1 text-gray-500 border-gray-200">
                                                Fab: {formatDate(batch.data_fabricacao)}
                                            </Badge>
                                        )}
                                    </div>
                                    <div className="text-[10px] text-muted-foreground uppercase tracking-wider font-bold">
                                        {status.label}
                                    </div>
                                </div>
                            </div>
                        );
                    })
                )}
            </div>
        </div>
    );
}

