/**
 * @module lote-recency
 *
 * Define a "janela recente" de lotes para impressão de etiquetas.
 *
 * Lotes não podem mais ser deletados (rastreabilidade: são referenciados por
 * movimentações e etiquetas_qr). Para evitar que lotes antigos sejam impressos
 * aleatoriamente, eles ficam ocultos por padrão na seleção/gestão de etiquetas
 * e só reaparecem via toggle "mostrar antigos".
 */

/**
 * Janela (em dias) que define um lote como "recente".
 * 2 = hoje + ontem. Alinhado à validade de 3–5 dias dos doces: praticamente
 * só produção fresca aparece sem o toggle.
 */
export const LOTE_RECENT_WINDOW_DAYS = 2;

/**
 * Retorna true se o lote é "recente" (dentro da janela).
 *
 * Usa `data_fabricacao` (data de produção) quando presente; senão cai para
 * `created_at`. Sem nenhuma data válida → considera recente (fail-safe: não
 * esconde o lote).
 *
 * Parsing via `'YYYY-MM-DD' + 'T12:00:00'` para evitar shift de fuso (Brasília
 * é UTC-3), seguindo o padrão já usado no resto do código de lotes.
 *
 * @param dataFabricacao - Data de fabricação do lote (string ISO ou null).
 * @param createdAt - created_at do lote, usado como fallback (string ISO ou null).
 * @param windowDays - Tamanho da janela em dias (default {@link LOTE_RECENT_WINDOW_DAYS}).
 */
export function isLoteRecente(
  dataFabricacao?: string | null,
  createdAt?: string | null,
  windowDays: number = LOTE_RECENT_WINDOW_DAYS,
): boolean {
  const ref = dataFabricacao || createdAt;
  if (!ref) return true;

  const refDate = new Date(ref.slice(0, 10) + 'T12:00:00');
  if (Number.isNaN(refDate.getTime())) return true;

  const cutoff = new Date();
  cutoff.setHours(12, 0, 0, 0);
  cutoff.setDate(cutoff.getDate() - (windowDays - 1));

  return refDate.getTime() >= cutoff.getTime();
}

