import { describe, it, expect } from 'vitest';
import { isLoteRecente, LOTE_RECENT_WINDOW_DAYS } from './lote-recency';

/** Data local (YYYY-MM-DD) de N dias atrás, ao meio-dia — sem shift de fuso. */
function dateDaysAgo(days: number): string {
  const d = new Date();
  d.setHours(12, 0, 0, 0);
  d.setDate(d.getDate() - days);
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

describe('isLoteRecente (janela padrão = 2 dias: hoje + ontem)', () => {
  it('lote de hoje é recente', () => {
    expect(isLoteRecente(dateDaysAgo(0), null)).toBe(true);
  });

  it('lote de ontem é recente', () => {
    expect(isLoteRecente(dateDaysAgo(1), null)).toBe(true);
  });

  it('lote de 2 dias atrás é antigo', () => {
    expect(isLoteRecente(dateDaysAgo(2), null)).toBe(false);
  });

  it('lote de 5 dias atrás é antigo', () => {
    expect(isLoteRecente(dateDaysAgo(5), null)).toBe(false);
  });

  it('cai para created_at quando data_fabricacao é nula', () => {
    expect(isLoteRecente(null, dateDaysAgo(0))).toBe(true);
    expect(isLoteRecente(null, dateDaysAgo(5))).toBe(false);
  });

  it('prioriza data_fabricacao sobre created_at', () => {
    expect(isLoteRecente(dateDaysAgo(0), dateDaysAgo(30))).toBe(true);
    expect(isLoteRecente(dateDaysAgo(10), dateDaysAgo(0))).toBe(false);
  });

  it('aceita created_at com timestamp completo', () => {
    const hoje = dateDaysAgo(0);
    expect(isLoteRecente(null, `${hoje}T08:30:00Z`)).toBe(true);
  });

  it('sem nenhuma data → recente (fail-safe, não esconde)', () => {
    expect(isLoteRecente(null, null)).toBe(true);
    expect(isLoteRecente(undefined, undefined)).toBe(true);
  });

  it('data inválida → recente (fail-safe)', () => {
    expect(isLoteRecente('not-a-date', null)).toBe(true);
  });

  it('respeita windowDays customizado', () => {
    expect(isLoteRecente(dateDaysAgo(4), null, 5)).toBe(true);
    expect(isLoteRecente(dateDaysAgo(5), null, 5)).toBe(false);
  });

  it('LOTE_RECENT_WINDOW_DAYS é 2', () => {
    expect(LOTE_RECENT_WINDOW_DAYS).toBe(2);
  });
});

