    expect(isLoteRecente(dateDaysAgo(4), null, 5)).toBe(true);
    expect(isLoteRecente(dateDaysAgo(5), null, 5)).toBe(false);
  });

  it('LOTE_RECENT_WINDOW_DAYS é 2', () => {
    expect(LOTE_RECENT_WINDOW_DAYS).toBe(2);
  });
